configuration.example_policy:
{
  "policy_name": "Banking Cryptographic Standards",
  "version": "1.0",
  "rules": [
    {
      "id": "no-md5-sha1",
      "severity": "CRITICAL",
      "description": "Prohibit MD5 and SHA-1 for security purposes",
      "condition": {
        "algorithm": ["MD5", "SHA-1"],
        "usage_context": ["signature", "integrity", "authentication"]
      },
      "action": "BLOCK"
    },
    {
      "id": "minimum-rsa-key-size",
      "severity": "CRITICAL",
      "description": "RSA keys must be at least 2048 bits",
      "condition": {
        "algorithm": "RSA",
        "key_size": {"less_than": 2048}
      },
      "action": "BLOCK"
    },
    {
      "id": "prefer-aead-ciphers",
      "severity": "HIGH",
      "description": "Prefer AEAD cipher modes (GCM, CCM)",
      "condition": {
        "algorithm": ["AES-CBC", "AES-ECB"],
        "mode": ["CBC", "ECB"]
      },
      "action": "WARN"
    },
    {
      "id": "quantum-risk-assessment",
      "severity": "MEDIUM",
      "description": "Flag non-quantum-safe algorithms for long-term data",
      "condition": {
        "algorithm": ["RSA", "ECDSA", "DH", "ECDH"],
        "data_lifetime": {"greater_than": "5 years"}
      },
      "action": "WARN"
    }
  ]
}

pattern.implementation:
# Jenkins pipeline example
stage('Cryptographic Analysis') {
    steps {
        sh 'qse-scan --input target/myapp.jar --policy qse-policy.json --output qse-report.json'
        script {
            def report = readJSON file: 'qse-report.json'
            if (report.summary.critical > 0) {
                error("CRITICAL cryptographic findings detected. Build blocked.")
            }
            if (report.summary.high > 0) {
                input message: "HIGH severity findings detected. Approve to continue?"
            }
        }
    }
}

